class NomAreas extends BaseNomAreas {

    /**
     * Obtener un listado de los datos de las areas.
     *
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de las areas.
     */
    public static function obtenerListadoAreas($inicio = 0, $limite = 10, $idestructura) {

        //Devolviendo el listado de areas en forma de arreglo.
        $query = new Doctrine_Query ();        
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomAreas')
			->where("idestructura = $idestructura" )
            ->orderby('orden','asc')
            ->limit($limite)
            ->offset($inicio)
            ->fetchArray():  
        $query->rom('NomAreas')
			->where("idestructura = $idestructura" )
            ->orderby('orden','asc')
            ->fetchArray();
        
        return $result;
    }

    /**
     * Obtener todos las áreas.
     *
     * @return array    Listado de los datos de las areas.
     */
    public static function obtenerTodosAreas($idestructura){
        //Devolviendo el listado de areas en forma de arreglo.
        return Doctrine_Query::create()
            ->from('NomAreas')
			->where("idestructura = $idestructura" )
            ->orderby('orden','asc')
            ->fetchArray();
    }

    public static function obtenerAreas($idestructura){
        //Devolviendo el listado de areas en forma de arreglo.
        return Doctrine_Query::create()->select('idarea as idarea,denominacion as area, idestructura as idestructura, composicion')
            ->from('NomAreas')
            ->where("idestructura = $idestructura")
            ->orderby('orden','asc')
            ->fetchArray();
    }

    /**
     * Obtener la cantidad total de areas.
     *
     * @return int   Cantidad total de areas.
     */
    public static function obtenerCantidadTotalAreas($idestructura) {

        //Devolviendo la cantidad total de areas.
        return Doctrine_Query::create()->select('COUNT(idarea) AS cantidad')
            ->from('NomAreas')
			->where("idestructura = $idestructura" )
            ->fetchOne()
            ->cantidad;
    }

    /**
     * Obtener el area dado el identificador.
     *
     * @param int $idarea    Identificador del area.
     * @return Nomarea   Objeto area (clase del dominio).
     */
    public static function obtenerObjAreasDadoId($idarea) {
        return Doctrine::getTable('NomAreas')->find($idarea);
    }

    /**
     * Obtener si existe un area a partir de la denominaci�n.
     *
     * @param int $idarea    	Identificador del area.
     * @param string $denom    	 	Denominaci�n del area.
     *
     * @return boolean    			Si existe el area.
     */
    public static function existeArea($idarea, $denom) {

        $query = Doctrine_Query::create()->select('COUNT(idarea) AS cantidad')
            ->from('NomAreas')
            ->where("denominacion ilike ?", $denom);
        if($idarea){
            $query->addWhere('idarea <> ?', $idarea);
        }

        return    $query->fetchOne()->cantidad;
    }



    /**********************************VER DE AQUI *******************************************/
    public static function existeDenominacionArea($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomAreas p')
            ->where("p.denominacion=?", array($denominacion))
            ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
            ->execute();
        if(count($result)){
            return 1;
        }else{
            return 0;
        }
    }

    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idarea = null, $idestructura)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomAreas')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom' and idestructura = '$idestructura'");
            if (!empty($idarea)) {
                $query->andWhere("idarea <> ?", $idarea);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }
    
	
}
